create or replace function public.crm_experiment_report(p_experiment_id uuid) returns jsonb language sql stable set search_path=public as $$
with e as(select id as experiment_id from public.crm_experiments where id=p_experiment_id and user_id=auth.uid()),v as(
 select v.id,v.name,v.weight,count(distinct x.subject_key)::int exposures,count(distinct case when o.outcome='converted' then o.subject_key end)::int conversions,coalesce(sum(case when o.outcome='revenue' then o.value else 0 end),0) revenue
 from public.crm_experiment_variants v join e on e.experiment_id=v.experiment_id left join public.crm_experiment_exposures x on x.variant_id=v.id left join public.crm_experiment_outcomes o on o.variant_id=v.id and o.subject_key=x.subject_key group by v.id,v.name,v.weight
),s as(select v.*,case when exposures>0 then conversions::numeric/exposures else 0 end rate from v),ci as(
 select s.*,case when exposures>0 then (rate+1.96^2/(2*exposures)-1.96*sqrt((rate*(1-rate)+1.96^2/(4*exposures))/exposures))/(1+1.96^2/exposures) else 0 end lower95,case when exposures>0 then (rate+1.96^2/(2*exposures)+1.96*sqrt((rate*(1-rate)+1.96^2/(4*exposures))/exposures))/(1+1.96^2/exposures) else 0 end upper95 from s
),eligible as(select * from ci where exposures>=100),best as(select eligible.* from eligible order by rate desc,revenue desc,id limit 1),totals as(select coalesce(sum(exposures),0)::int exposures,coalesce(sum(conversions),0)::int conversions,coalesce(sum(revenue),0) revenue)
select jsonb_build_object('experiment_id',p_experiment_id,'variants',coalesce((select jsonb_agg(jsonb_build_object('variant_id',ci.id,'name',ci.name,'weight',ci.weight,'exposures',ci.exposures,'conversions',ci.conversions,'conversion_rate',round(ci.rate,6),'revenue',ci.revenue,'ci95_lower',round(ci.lower95,6),'ci95_upper',round(ci.upper95,6),'eligible_for_winner',ci.exposures>=100) order by ci.name) from ci),'[]'::jsonb),'totals',(select to_jsonb(totals) from totals),'learning',coalesce((select jsonb_agg(jsonb_build_object('variant_id',ci.id,'name',ci.name,'conversion_rate',round(ci.rate,6),'lift_vs_best',case when best.rate>0 then round((ci.rate-best.rate)/best.rate,6) else 0 end,'sample_size',ci.exposures,'ci95_lower',round(ci.lower95,6),'ci95_upper',round(ci.upper95,6),'confidence_level','95_percent_wilson_descriptive') order by ci.rate desc) from ci cross join best),'[]'::jsonb),'recommended_variant',(select jsonb_build_object('variant_id',best.id,'name',best.name,'conversion_rate',round(best.rate,6),'ci95_lower',round(best.lower95,6),'ci95_upper',round(best.upper95,6),'reason','Maior conversão observada entre variantes com pelo menos 100 exposições; intervalo Wilson de 95%, sem alegação causal.') from best),'generated_at',now());
$$;
revoke all on function public.crm_experiment_report(uuid) from anon;
grant execute on function public.crm_experiment_report(uuid) to authenticated;
